let highlighted;fetch(new URL(document.URL).pathname+"index.json").then(e=>e.json()).then(e=>{highlighted=e.highlighted});function randomHighlighted(){const e=new Set;for(;e.size!=6;)e.add(Math.round(Math.random()*(highlighted.length-1)));let t="";const n=Array.from(e).map(e=>highlighted[e]);for(let e of n)t+=formatItem(e);document.getElementById("highlightedItems").innerHTML=t}document.getElementById("highlightedButton").addEventListener("click",e=>{e.preventDefault(),randomHighlighted()})